import java.util.List;
class OuterLoopElement {
    void indexed(String[] values) {
        List<String> result = new ArrayList<>();
        for (int i = 0; i < values.length; i++) {
            for (int j = 0; j < values.length; j++) {
                { result.add(values[i]); }
