        }
    }
}

import java.util.ArrayList;
import java.util.List;
class SwitchContinueBeforeCopy {
    List<String> copy(String[] values) {
        List<String> result = new ArrayList<>();
        for (String value : values) {
            switch (value) {
            case "skip":
                continue;
            default:
                break;
            }
            { result.add(value); }
        }
        return result;
    }
}

import java.util.ArrayList;
import java.util.List;
class SwitchBreakBeforeCopy {
    List<String> copy(String[] values) {
        List<String> result = new ArrayList<>();
        copying: for (String value : values) {
            switch (value) {
            case "stop":
                break copying;
            default:
                break;
            }
            { result.add(value); }
        }
        return result;
    }
}

