        }
        return result;
    }
}

import java.util.ArrayList;
import java.util.List;
class TryContinueBeforeCopy {
    List<String> copy(String[] values) {
        List<String> result = new ArrayList<>();
        for (String value : values) {
            try {
                Integer.parseInt(value);
            } catch (NumberFormatException ex) {
                continue;
            }
            { result.add(value); }
        }
        return result;
    }
}

import java.util.ArrayList;
import java.util.List;
class TryBreakBeforeCopy {
    List<String> copy(String[] values) {
        List<String> result = new ArrayList<>();
        for (String value : values) {
            try {
                if (value.isEmpty()) {
                    break;
                }
            } finally {
            }
            { result.add(value); }
        }
        return result;
    }
}

import java.util.ArrayList;
import java.util.List;
class ExtraSideEffect {
    int calls;
    List<String> copy(String[] values) {
        List<String> result = new ArrayList<>();
        for (String value : values) {
            calls++;
            { result.add(value); }
        }
        return result;
    }
    List<String> indexedCopy(String[] values) {
        List<String> result = new ArrayList<>();
        for (int i = 0; i < values.length; i++) {
            calls++;
            { result.add(values[i]); }
        }
        return result;
    }
}
